179	UserEmail.confirmByCode = async function (code, sessionId) {
180		const confirmObj = await db.getObject(`confirm:${code}`);
181		if (!confirmObj || !confirmObj.uid || !confirmObj.email ||
182			await db.get(`confirm:byUid:${confirmObj.uid}`) !== code ||
183			await db.pttl(`confirm:${code}`) <= 0 ||
184			await db.pttl(`confirm:byUid:${confirmObj.uid}`) <= 0) {
185			throw new Error('[[error:invalid-data]]');
186		}
187	
188		// If another uid has the same email, remove it
189		const oldUid = await db.sortedSetScore('email:uid', confirmObj.email.toLowerCase());
190		if (oldUid) {
191			await UserEmail.remove(oldUid, sessionId);
192		}
193	
194		const oldEmail = await user.getUserField(confirmObj.uid, 'email');
195		if (oldEmail && confirmObj.email !== oldEmail) {
196			await UserEmail.remove(confirmObj.uid, sessionId);
197		} else {
198			await user.auth.revokeAllSessions(confirmObj.uid, sessionId);
199		}
200	
201		await user.setUserField(confirmObj.uid, 'email', confirmObj.email);
202		await Promise.all([
203			UserEmail.confirmByUid(confirmObj.uid),
204			db.delete(`confirm:${code}`),
205			events.log({ type: 'email-change', oldEmail, newEmail: confirmObj.email }),
