111	describe('email confirmation lifecycle', () => {
112		const email = 'pending@example.org';
113		const expiryMs = 2 * 24 * 60 * 60 * 1000;
114		const intervalMs = 10 * 60 * 1000;
115		let uid;
116		let nextUser = 0;
117		let previousConfig;
118	
119		before(() => {
120			previousConfig = {
121				emailConfirmExpiry: meta.config.emailConfirmExpiry,
122				emailConfirmInterval: meta.config.emailConfirmInterval,
123				sendValidationEmail: meta.config.sendValidationEmail,
124			};
125			meta.config.emailConfirmExpiry = 2;
126			meta.config.emailConfirmInterval = 10;
127			meta.config.sendValidationEmail = 1;
128			plugins.hooks.register('email-confirmation-lifecycle-test', {
129				hook: 'filter:email.send',
130				method: async () => {},
131			});
132		});
133	
134		after(() => {
135			plugins.hooks.unregister('email-confirmation-lifecycle-test', 'filter:email.send');
136			Object.assign(meta.config, previousConfig);
137		});
138	
139		beforeEach(async () => {
140			nextUser += 1;
141			uid = await user.create({ username: `email-lifecycle-${nextUser}`, password: '123456' });
142		});
143	
144		it('returns strict pending booleans and null expiry without a confirmation', async () => {
145			assert.strictEqual(await user.email.isValidationPending(uid), false);
146			assert.strictEqual(await user.email.isValidationPending(uid, email), false);
147			assert.strictEqual(await user.email.getValidationExpiry(uid), null);
148			assert.strictEqual(await user.email.canSendValidation(uid, email), true);
149		});
150	
151		it('reports the live remaining confirmation lifetime in milliseconds', async () => {
152			await user.email.sendValidationEmail(uid, { email });
153			assert.strictEqual(await user.email.isValidationPending(uid), true);
154			assert.strictEqual(await user.email.isValidationPending(uid, email), true);
155			assert.strictEqual(await user.email.isValidationPending(uid, email.toUpperCase()), true);
156			assert.strictEqual(await user.email.isValidationPending(uid, 'other@example.org'), false);
157	
158			const originalTtl = await user.email.getValidationExpiry(uid);
159			const code = await db.get(`confirm:byUid:${uid}`);
160			const recordTtl = await db.pttl(`confirm:${code}`);
161			assert(Number.isFinite(originalTtl));
162			assert(originalTtl > 0 && originalTtl <= expiryMs);
163			assert(recordTtl > 0 && recordTtl <= expiryMs);
164			await db.pexpireAt(`confirm:byUid:${uid}`, Date.now() + 30000);
165			const reducedTtl = await user.email.getValidationExpiry(uid);
166			assert(reducedTtl > 0 && reducedTtl <= 30000);
167			assert(reducedTtl < originalTtl - 1000);
168		});
169	
170		it('clears both confirmation keys and permits an immediate resend after expiry', async () => {
171			const oldCode = await user.email.sendValidationEmail(uid, { email });
172			await user.email.expireValidation(uid);
173	
174			assert.strictEqual(await db.get(`confirm:byUid:${uid}`), null);
175			assert.strictEqual(await db.getObject(`confirm:${oldCode}`), null);
176			assert.strictEqual(await user.email.isValidationPending(uid), false);
177			assert.strictEqual(await user.email.getValidationExpiry(uid), null);
178			assert.strictEqual(await user.email.canSendValidation(uid, email), true);
179	
180			const newCode = await user.email.sendValidationEmail(uid, { email });
181			assert.notStrictEqual(newCode, oldCode);
182			assert.strictEqual(await user.email.isValidationPending(uid, email), true);
183		});
184	
185		it('blocks resend for the interval and replaces the old confirmation afterward', async () => {
186			const oldCode = await user.email.sendValidationEmail(uid, { email });
187			assert.strictEqual(await user.email.canSendValidation(uid, email), false);
188			await assert.rejects(
