192	
193			await db.pexpireAt(`confirm:byUid:${uid}`, Date.now() + expiryMs - intervalMs + 5000);
194			assert.strictEqual(await user.email.canSendValidation(uid, email), false);
195			await db.pexpireAt(`confirm:byUid:${uid}`, Date.now() + expiryMs - intervalMs - 5000);
196			assert.strictEqual(await user.email.canSendValidation(uid, email), true);
197	
198			const newCode = await user.email.sendValidationEmail(uid, { email });
199			assert.notStrictEqual(newCode, oldCode);
200			assert.strictEqual(await db.getObject(`confirm:${oldCode}`), null);
201			assert.strictEqual(await user.email.isValidationPending(uid, email), true);
202		});
